import{_ as r,o,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-06-03:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-06-03:: Ceph Orchestration Meeting","date":"2019-06-03T00:00:00.000Z","updated":"2019-06-07T00:00:00.000Z","tags":["Ceph","分布式存储","orchestrator","Nautilus","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-03_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-06-03_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-06-03_-_-_Ceph_Orchestration_Meeting.md"};function i(a,t,p,n,u,_){return o(),l("div",null,[...t[0]||(t[0]=[e("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位Ceph研发人员，包括负责分布式存储Ceph的研发人员、视频会议字幕翻译及总结人员等。</p><p><strong>会议主题</strong>： 讨论Ceph Orchestrator和Nautilus的进展，以及相关技术挑战和解决方案。</p><p><strong>会议内容</strong>：</p><p><strong>1. Dashboard讨论</strong></p><ul><li>讨论将Dashboard集成到Orchestrator中的可行性，并确定Dashboard将主要关注集成到Orchestrator中。</li><li>讨论Dashboard的可用性和远程拨入的可能性，并计划在两周后的面对面会议中进一步讨论。</li></ul><p><strong>2. Nautilus进展</strong></p><ul><li>讨论Nautilus中Nathan提交的多个pull request。</li><li>讨论回滚Orchestrator更改的哲学，以及将更改回滚到master分支的目标。</li><li>讨论将Rook模块作为Rook模块添加到Octopus的可行性。</li></ul><p><strong>3. AP状态管理</strong></p><ul><li>讨论AP状态管理中的疑问和困难，特别是在没有使用AKS的情况下。</li><li>讨论默认配置和手动配置的问题。</li><li>讨论Rook允许创建多个对象存储区域，但没有允许它们跨集群工作的限制。</li><li>讨论最终用户对配置参数的控制。</li></ul><p><strong>4. Orchestrator API一致性</strong></p><ul><li>讨论不同Orchestrator之间API不一致性问题。</li><li>讨论是否应该将update操作仅实现于Rook和Kubernetes中，并使用其他Orchestrator的其他操作。</li><li>讨论如何使Dashboard能够处理不同Orchestrator的API调用。</li></ul><p><strong>5. Rook API更新</strong></p><ul><li>讨论Rook API的更新，包括添加新的命令和参数。</li><li>讨论如何处理Rook API中的update和remove操作。</li></ul><p><strong>6. Rook治理</strong></p><ul><li>讨论Jared提交的Rook治理更新PR，包括添加更多具有push访问权限的“所有者”。</li><li>讨论创建一个委员会来监督Rook项目。</li></ul><p><strong>7. 41.1版本发布</strong></p><ul><li>讨论即将发布的41.1版本，包括外部集群管理、OSD备份等功能。</li><li>讨论更新roadmap文档和功能板。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续讨论Dashboard和Orchestrator的集成。</li><li>完成Nautilus的pull request。</li><li>解决AP状态管理中的问题。</li><li>实现Orchestrator API一致性。</li><li>更新Rook API。</li><li>完成Rook治理更新。</li><li>发布41.1版本。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了多个英文关键词，例如“Orchestrator”、“Nautilus”、“Rook”、“AP”、“Kubernetes”等，这些关键词在会议讨论中占有重要地位。</li><li>会议纪要中尽量保留了原文的表述，以确保准确传达会议内容。</li></ul>",23)])])}const c=r(s,[["render",i]]);export{g as __pageData,c as default};
